            const res = await callWorkRpc(connection, 'sendChatMessage', { roomId, peerToken: activePeer?.isChannel ? undefined : activePeer?.peerToken, content: i === 0 ? text : '', type: file ? 'file' : 'text', fileMeta, replyTo });
